-- Scroll Overview: https://github.com/yayuuu/hyprland-scroll-overview
hl.config({
    plugin = {
        scrolloverview = {
            gesture_distance = 300, -- how far is the "max" for the gesture
            scale = 0.6, -- preferred overview scale
            workspace_gap = 80,
            layout = "vertical", -- vertical, horizontal, or auto (per-monitor orientation)
            wallpaper = 2, -- 0: global only, 1: per-workspace only, 2: both
            blur = true, -- blur only the main overview wallpaper

            shadow = {
                enabled = true,
                range = 50,
            },
        },
    },
})

-- Hikai owns overview presentation; Classic keeps the plugin through the facade.
hl.bind("SUPER + G", hl.dsp.exec_cmd("$HOME/.local/bin/window_navigator.sh overview-toggle"))
